-- v0.233 — Formulário "Lead: qualificação" da Mathisa: perguntas novas, pontuação, regras de produto, aviso de investimento e mensagem final.
-- Decisões da Rebecka (02/11): este é o formulário de captação da página; junta as perguntas do "Lead: qualificação" com as da antiga
-- "Captação: diagnóstico inicial de crescimento" (sem a pergunta de estratégia), com o aviso de investimento mínimo de R$ 3.500;
-- faturamento até R$ 10 mil e "ainda não vendo" ficam de fora (não qualificado, tag "qualif: nutrir").
-- Pontuação de 0 a 100: Porte (até 50), Estrutura (até 30) e Momento (até 20).
-- Produto (tag): full brain = Porte >= 32 e Estrutura >= 15; strategy = Porte >= 18; starter = o resto.
-- Temperatura (tag): quente = Momento >= 15 e total >= 50; morno = total >= 30; frio = o resto.
-- "Que tipo de ajuda você procura" põe "pediu: …"; se não bater com o produto indicado, entra "qualif: revisar".
-- Só roda se o formulário ainda não tiver respostas (troca as perguntas). Rode DEPOIS de RODAR_v0.233_qualificacao_blocos.sql.
do $rodar$
declare v_ws uuid; v_p uuid := '0d40f550-9e05-4b25-99cd-1353b221574f';
begin
  select workspace_id into v_ws from pesquisas where id = v_p;
  if v_ws is null then raise exception 'Formulário "Lead: qualificação" não encontrado.'; end if;
  if not exists (select 1 from workspaces where id = v_ws and agencia) then raise exception 'Este formulário não está no workspace da Mathisa.'; end if;
  if exists (select 1 from pesquisa_respostas where pesquisa_id = v_p) then raise exception 'O formulário já tem respostas: não troquei as perguntas. Fale com o Claude.'; end if;
  if not exists (select 1 from information_schema.columns where table_name = 'pesquisa_respostas' and column_name = 'qualif_det') then raise exception 'Rode antes o RODAR_v0.233_qualificacao_blocos.sql.'; end if;
  delete from pesquisa_perguntas where pesquisa_id = v_p;
  insert into pesquisa_perguntas (workspace_id, pesquisa_id, ordem, texto, tipo, obrigatoria, papel, opcoes, pontos) values (v_ws, v_p, 1, 'Qual é o seu principal objetivo hoje?', 'texto', true, 'qualificacao', '{}'::text[], null);
  insert into pesquisa_perguntas (workspace_id, pesquisa_id, ordem, texto, tipo, obrigatoria, papel, opcoes, pontos) values (v_ws, v_p, 2, 'Você vende produto digital hoje? Há quanto tempo?', 'escolha', true, 'qualificacao', array['Ainda não vendo', 'Menos de 1 ano', '1 a 3 anos', 'Mais de 3 anos']::text[], '{"opcoes": {"Ainda não vendo": {"p": 0, "tag": "qualif: nutrir", "elim": true}, "Menos de 1 ano": {"p": 2}, "1 a 3 anos": {"p": 5}, "Mais de 3 anos": {"p": 7}}, "bloco": "Estrutura"}'::jsonb);
  insert into pesquisa_perguntas (workspace_id, pesquisa_id, ordem, texto, tipo, obrigatoria, papel, opcoes, pontos) values (v_ws, v_p, 3, 'Qual é o faturamento médio mensal do seu negócio?', 'escolha', true, 'qualificacao', array['Até R$ 10 mil', 'De R$ 10 mil a R$ 30 mil', 'De R$ 30 mil a R$ 100 mil', 'De R$ 100 mil a R$ 250 mil', 'Acima de R$ 250 mil']::text[], '{"opcoes": {"Até R$ 10 mil": {"p": 0, "tag": "qualif: nutrir", "elim": true}, "De R$ 10 mil a R$ 30 mil": {"p": 5}, "De R$ 30 mil a R$ 100 mil": {"p": 15}, "De R$ 100 mil a R$ 250 mil": {"p": 22}, "Acima de R$ 250 mil": {"p": 25}}, "bloco": "Porte"}'::jsonb);
  insert into pesquisa_perguntas (workspace_id, pesquisa_id, ordem, texto, tipo, obrigatoria, papel, opcoes, pontos) values (v_ws, v_p, 4, 'Quantos produtos você vende hoje?', 'escolha', true, 'qualificacao', array['1', '2 a 3', '4 ou mais']::text[], '{"opcoes": {"1": {"p": 2}, "2 a 3": {"p": 5}, "4 ou mais": {"p": 7}}, "bloco": "Porte"}'::jsonb);
  insert into pesquisa_perguntas (workspace_id, pesquisa_id, ordem, texto, tipo, obrigatoria, papel, opcoes, pontos) values (v_ws, v_p, 5, 'Qual é o ticket médio do seu principal produto?', 'escolha', true, 'qualificacao', array['Até R$ 500', 'De R$ 500 a R$ 2 mil', 'De R$ 2 mil a R$ 10 mil', 'Acima de R$ 10 mil']::text[], '{"opcoes": {"Até R$ 500": {"p": 2}, "De R$ 500 a R$ 2 mil": {"p": 5}, "De R$ 2 mil a R$ 10 mil": {"p": 8}, "Acima de R$ 10 mil": {"p": 10}}, "bloco": "Porte"}'::jsonb);
  insert into pesquisa_perguntas (workspace_id, pesquisa_id, ordem, texto, tipo, obrigatoria, papel, opcoes, pontos) values (v_ws, v_p, 6, 'Como você vende hoje? (pode marcar mais de uma)', 'multipla', true, 'qualificacao', array['Lançamentos', 'Vendas no automático (perpétuo)', 'Venda direta por WhatsApp ou chamada (high ticket)', 'Assinatura ou recorrência']::text[], '{"opcoes": {"Lançamentos": {"p": 2}, "Vendas no automático (perpétuo)": {"p": 2}, "Venda direta por WhatsApp ou chamada (high ticket)": {"p": 2}, "Assinatura ou recorrência": {"p": 2}}, "bloco": "Estrutura"}'::jsonb);
  insert into pesquisa_perguntas (workspace_id, pesquisa_id, ordem, texto, tipo, obrigatoria, papel, opcoes, pontos) values (v_ws, v_p, 7, 'Quanto você investe em anúncios por mês?', 'escolha', true, 'qualificacao', array['Não invisto', 'Até R$ 5 mil', 'De R$ 5 mil a R$ 20 mil', 'Acima de R$ 20 mil']::text[], '{"opcoes": {"Não invisto": {"p": 0}, "Até R$ 5 mil": {"p": 3}, "De R$ 5 mil a R$ 20 mil": {"p": 6}, "Acima de R$ 20 mil": {"p": 8}}, "bloco": "Porte"}'::jsonb);
  insert into pesquisa_perguntas (workspace_id, pesquisa_id, ordem, texto, tipo, obrigatoria, papel, opcoes, pontos) values (v_ws, v_p, 8, 'Como você acompanha os resultados do negócio atualmente?', 'escolha', true, 'qualificacao', array['Não tenho uma rotina estruturada.', 'Uso relatórios das plataformas e planilhas.', 'Tenho dashboards, mas as informações estão fragmentadas.', 'Tenho dados integrados e indicadores confiáveis.']::text[], '{"opcoes": {"Não tenho uma rotina estruturada.": {"p": 0}, "Uso relatórios das plataformas e planilhas.": {"p": 3}, "Tenho dashboards, mas as informações estão fragmentadas.": {"p": 6}, "Tenho dados integrados e indicadores confiáveis.": {"p": 8}}, "bloco": "Estrutura"}'::jsonb);
  insert into pesquisa_perguntas (workspace_id, pesquisa_id, ordem, texto, tipo, obrigatoria, papel, opcoes, pontos) values (v_ws, v_p, 9, 'Como está organizada sua equipe?', 'escolha', true, 'qualificacao', array['Faço praticamente tudo sozinho(a).', 'Tenho uma equipe pequena que pode executar melhorias.', 'Tenho profissionais de marketing, vendas e operação.', 'Tenho uma equipe estruturada, incluindo tecnologia e dados.']::text[], '{"opcoes": {"Faço praticamente tudo sozinho(a).": {"p": 0}, "Tenho uma equipe pequena que pode executar melhorias.": {"p": 2}, "Tenho profissionais de marketing, vendas e operação.": {"p": 5}, "Tenho uma equipe estruturada, incluindo tecnologia e dados.": {"p": 7}}, "bloco": "Estrutura"}'::jsonb);
  insert into pesquisa_perguntas (workspace_id, pesquisa_id, ordem, texto, tipo, obrigatoria, papel, opcoes, pontos) values (v_ws, v_p, 10, 'Qual é o principal desafio do seu negócio hoje?', 'escolha', true, 'alavanca', array['Tenho dificuldade para entender meus números e saber onde melhorar.', 'Não consigo identificar onde meu negócio está perdendo dinheiro ou eficiência.', 'Tenho dados, mas falta uma estratégia clara de crescimento.', 'Não consigo enxergar o negócio de ponta a ponta.', 'Minhas ferramentas e informações estão desconectadas.', 'Preciso de automações, infraestrutura e inteligência para escalar.']::text[], null);
  insert into pesquisa_perguntas (workspace_id, pesquisa_id, ordem, texto, tipo, obrigatoria, papel, opcoes, pontos) values (v_ws, v_p, 11, 'Quer contar mais sobre esse desafio?', 'texto', false, 'alavanca', '{}'::text[], null);
  insert into pesquisa_perguntas (workspace_id, pesquisa_id, ordem, texto, tipo, obrigatoria, papel, opcoes, pontos) values (v_ws, v_p, 12, 'Que tipo de ajuda você procura neste momento?', 'escolha', true, 'qualificacao', array['Orientação para organizar números, analisar e melhorar os resultados.', 'Ajuda para construir uma estratégia de crescimento com a participação da minha equipe.', 'Especialistas para investigar meu negócio e construir o plano.', 'Implementação de dados, integrações, automações e inteligência contínua.', 'Ainda não sei exatamente do que preciso.']::text[], '{"opcoes": {"Orientação para organizar números, analisar e melhorar os resultados.": {"p": 0, "tag": "pediu: starter"}, "Ajuda para construir uma estratégia de crescimento com a participação da minha equipe.": {"p": 0, "tag": "pediu: strategy"}, "Especialistas para investigar meu negócio e construir o plano.": {"p": 0, "tag": "pediu: strategy"}, "Implementação de dados, integrações, automações e inteligência contínua.": {"p": 0, "tag": "pediu: full brain"}}}'::jsonb);
  insert into pesquisa_perguntas (workspace_id, pesquisa_id, ordem, texto, tipo, obrigatoria, papel, opcoes, pontos) values (v_ws, v_p, 13, 'Quando pretende começar?', 'escolha', true, 'qualificacao', array['Agora', 'Em até 30 dias', 'Ainda estou avaliando']::text[], '{"opcoes": {"Agora": {"p": 20}, "Em até 30 dias": {"p": 15}, "Ainda estou avaliando": {"p": 5}}, "bloco": "Momento"}'::jsonb);
  update pesquisas set ativa = true, aceita_link_aberto = true,
    qualif = '{"ativa": true, "modo": "soma", "corte": 0, "faixas": [], "grupos": [{"nome": "Produto", "regras": [{"tag": "qualif: full brain", "se": {"Porte": {"min": 32}, "Estrutura": {"min": 15}}}, {"tag": "qualif: strategy", "se": {"Porte": {"min": 18}}}, {"tag": "qualif: starter", "se": {}}]}, {"nome": "Temperatura", "regras": [{"tag": "lead: quente", "se": {"Momento": {"min": 15}, "total": {"min": 50}}}, {"tag": "lead: morno", "se": {"total": {"min": 30}}}, {"tag": "lead: frio", "se": {}}]}], "confere": {"pediu": "pediu: ", "indicado": "qualif: ", "tag": "qualif: revisar"}}'::jsonb,
    captacao = coalesce(captacao, '{}'::jsonb) || '{"ativa": true, "destino": "lead", "etapa_id": "", "responsavel_id": "", "tags": ["Formulário de qualificação"], "campos": {"telefone": {"mostrar": true, "obrig": true, "rotulo": "WhatsApp"}, "instagram": {"mostrar": true, "obrig": true, "rotulo": "Instagram do negócio"}}, "aviso_titulo": "Informação sobre investimento", "aviso_texto": "O investimento mínimo para contratar uma solução da Mathisa é de R$ 3.500. O valor final depende do escopo e será apresentado após a avaliação da necessidade.", "consentimentos": [{"obrig": true, "texto": "Estou ciente do investimento mínimo informado e desejo seguir com minha solicitação."}, {"obrig": true, "texto": "Autorizo o uso dos meus dados e respostas para análise da solicitação e contato comercial sobre os serviços da Mathisa."}, {"obrig": false, "texto": "Quero receber também conteúdos e novidades da Mathisa."}], "nota_final": "As respostas serão utilizadas para orientar a análise comercial. A oferta recomendada será validada pela equipe.", "passo_contato": "Seus dados", "passo_final": "Alinhamento", "sucesso_titulo": "Recebemos suas respostas!", "sucesso_texto": "Obrigada por contar sobre o seu negócio. Nossa equipe vai analisar suas respostas e chamar você no WhatsApp que você informou em até 1 dia útil, para conversar sobre o melhor caminho para você."}'::jsonb
  where id = v_p;
end $rodar$;
